cd /app && mkdir -p output && cat > output/styles.css <<'EOF'
:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --text: #1d1d1f;
  --muted: #6e6e73;
  --link: #0066cc;
  --line: #d2d2d7;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
}
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(1200px, 92vw); margin: 0 auto; }
.topnav { background: rgba(255,255,255,.88); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); position: sticky; top:0; z-index: 40; }
.topnav .inner { display:flex; align-items:center; justify-content:space-between; padding: 10px 0; gap: 12px; }
.brand { font-weight: 700; letter-spacing: .2px; }
.nav-links { display:flex; gap:16px; flex-wrap: wrap; }
.hero { padding: 42px 0 28px; background: linear-gradient(180deg,#fff,#f8f8fa); }
.hero h1 { font-size: clamp(40px,6vw,56px); line-height:1.05; margin:0; }
.hero p { margin:12px 0 0; color: var(--muted); font-size: clamp(18px,2.3vw,28px); }
.hero-ctas { margin-top:16px; display:flex; gap:20px; flex-wrap:wrap; }
.section { padding: 42px 0; }
.section h2 { margin:0; font-size: clamp(28px,4vw,44px); line-height:1.1; }
.section .sub { margin-top: 8px; color: var(--muted); font-size: clamp(16px,2vw,22px); }
.categories { display:flex; gap:14px; overflow-x:auto; padding: 14px 0 4px; scroll-snap-type: x proximity; }
.cat { min-width: 120px; background:#fff; border:1px solid var(--line); border-radius:18px; padding:14px 10px; text-align:center; scroll-snap-align:start; }
.cat .icn { width:42px; height:30px; margin:0 auto 8px; border-radius:8px; background: linear-gradient(140deg,#d9d9de,#fdfdff); }
.carousel-wrap { position: relative; margin-top: 20px; }
.carousel { display:flex; gap:16px; overflow-x:auto; scroll-behavior:smooth; padding: 4px 4px 8px; scrollbar-width: none; }
.carousel::-webkit-scrollbar { display:none; }
.card { min-width: 280px; max-width: 280px; background: var(--surface); border-radius: 22px; padding: 18px; border:1px solid #ebebef; box-shadow: 0 2px 8px rgba(0,0,0,.03); }
.card .badge { color:#b56a00; font-size:12px; font-weight:700; letter-spacing:.4px; }
.card .img { height: 150px; border-radius: 14px; margin: 10px 0 12px; background: linear-gradient(145deg,#dce8ff,#f6f8ff 45%,#f6ece2); }
.card h3 { margin:0; font-size: 22px; }
.card p { margin:8px 0 0; color: var(--muted); font-size: 14px; min-height: 38px; }
.price { margin-top: 12px; font-weight: 600; }
.monthly { color: var(--muted); font-size: 14px; margin-top: 4px; }
.arrow { position:absolute; top: 42%; transform: translateY(-50%); width:40px; height:40px; border:none; border-radius:50%; background:#fff; box-shadow:0 2px 10px rgba(0,0,0,.16); cursor:pointer; z-index:2; }
.arrow.prev { left:-10px; }
.arrow.next { right:-10px; }
.tile-grid { display:grid; grid-template-columns: repeat(2,1fr); gap:16px; margin-top: 18px; }
.tile { min-height: 380px; background:#fff; border-radius: 24px; padding: 26px; display:flex; flex-direction:column; justify-content:space-between; border:1px solid #ececf0; }
.tile .visual { height:200px; border-radius:18px; background: linear-gradient(135deg,#d7e7ff,#f4f6ff,#ffece6); }
.tile h3 { font-size: 34px; margin: 0; }
.tile p { margin: 8px 0 0; color: var(--muted); }
.cta-row { display:flex; gap:16px; margin-top:10px; }
.tabs { display:flex; gap:10px; flex-wrap:wrap; margin-top:18px; }
.tab-btn { border:1px solid var(--line); background:#fff; border-radius: 999px; padding:10px 16px; cursor:pointer; }
.tab-btn.active { background: var(--text); color:#fff; border-color: var(--text); }
.tab-panel { display:none; margin-top:14px; }
.tab-panel.active { display:block; }
.sticky-subnav { position: sticky; top: 52px; z-index: 30; background: rgba(245,245,247,.95); border-bottom:1px solid var(--line); }
.sticky-subnav .links { display:flex; gap:8px; overflow-x:auto; padding:10px 0; }
.sticky-subnav a { display:inline-block; white-space:nowrap; padding:8px 14px; background:#fff; border:1px solid var(--line); border-radius:999px; color:var(--text); font-size:14px; }
.quick-links { display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; }
.quick-links a { background:#fff; border:1px solid var(--line); border-radius:999px; padding:9px 14px; color:var(--text); }
.footer { margin-top: 40px; background:#fff; border-top: 1px solid var(--line); }
.footer .cols { display:grid; grid-template-columns: repeat(4,1fr); gap:18px; padding: 24px 0; }
.footer h4 { margin:0 0 8px; font-size:14px; }
.footer ul { list-style:none; margin:0; padding:0; display:grid; gap:8px; }
.footer li { color: var(--muted); font-size: 13px; }
.acc-head { display:none; }
@media (max-width: 960px) {
  .tile-grid { grid-template-columns:1fr; }
  .footer .cols { grid-template-columns:1fr 1fr; }
}
@media (max-width: 700px) {
  .arrow { display:none; }
  .card { min-width: 82vw; max-width:82vw; }
  .hero { padding-top: 28px; }
  .footer .cols { grid-template-columns: 1fr; gap:0; }
  .footer .col { border-top:1px solid var(--line); padding: 0; }
  .acc-head { display:flex; align-items:center; justify-content:space-between; width:100%; text-align:left; border:none; background:transparent; font-size:14px; padding:14px 0; cursor:pointer; }
  .footer .col ul { display:none; padding:0 0 12px; }
  .footer .col.open ul { display:grid; }
}
EOF

cat > output/app.js <<'EOF'
function setupCarousels() {
  document.querySelectorAll('[data-carousel-wrap]').forEach((wrap) => {
    const carousel = wrap.querySelector('.carousel');
    if (!carousel) return;
    const prev = wrap.querySelector('.arrow.prev');
    const next = wrap.querySelector('.arrow.next');
    const step = () => Math.max(260, Math.floor(carousel.clientWidth * 0.82));
    prev?.addEventListener('click', () => carousel.scrollBy({ left: -step(), behavior: 'smooth' }));
    next?.addEventListener('click', () => carousel.scrollBy({ left: step(), behavior: 'smooth' }));
  });
}

function setupTabs() {
  const container = document.querySelector('[data-tabs]');
  if (!container) return;
  const buttons = container.querySelectorAll('.tab-btn');
  const panels = container.querySelectorAll('.tab-panel');
  buttons.forEach((btn) => {
    btn.addEventListener('click', () => {
      buttons.forEach((b) => b.classList.remove('active'));
      panels.forEach((p) => p.classList.remove('active'));
      btn.classList.add('active');
      container.querySelector(`[data-panel="${btn.dataset.tab}"]`)?.classList.add('active');
    });
  });
}

function setupFooterAccordion() {
  if (window.matchMedia('(max-width: 700px)').matches) {
    document.querySelectorAll('.footer .col').forEach((col) => {
      const btn = col.querySelector('.acc-head');
      btn?.addEventListener('click', () => col.classList.toggle('open'));
    });
  }
}

document.addEventListener('DOMContentLoaded', () => {
  setupCarousels();
  setupTabs();
  setupFooterAccordion();
});
EOF

